-- Black Friday 2026 : 1 € sous le prix promo de LedPerf, sur tout le catalogue.
--
-- Demande de l'exploitant (20 novembre 2026) : « je veux être moins cher que
-- LedPerf sur tous les produits, avec le badge promo comme eux, 1 € moins
-- cher ». LedPerf fait -20 % sur tout son site (code bf26) ; sur Google
-- Shopping, LEDVROOM était de 15 à 26 % plus cher pour les mêmes packs.
--
-- Pour chaque variante :
--   1. Prix de LedPerf connu (packs relevés le 19 octobre, `priceSourceCents`
--      de prisma/packs-vehicule*.json) : prix LedPerf × 0,8 − 1 €.
--   2. Sinon : le catalogue a été tarifé à « LedPerf − 5 %, arrondi au ,90 le
--      plus proche, strictement en dessous ». Le prix LedPerf est donc au moins
--      max(prix + 1 centime, (prix − 0,50 €) / 0,95). On part de cette borne
--      basse : le résultat est toujours au moins 1 € sous LedPerf.
--   3. Jamais en dessous de la moitié du prix actuel (petites pièces à
--      quelques centimes), ni du prix d'achat TTC quand il est renseigné.
--   4. L'ancien prix devient le prix barré (`compareAtCents`) : c'est le prix
--      pratiqué jusqu'ici, la référence qu'exige l'annonce d'une réduction.
--
-- Les valeurs d'avant sont gardées dans "PrixAvantPromotion" (campagne
-- « black-friday-2026 »). Pour revenir en arrière à la fin de la campagne :
--
--   UPDATE "ProductVariant" v
--   SET "priceCents" = a."priceCents", "compareAtCents" = a."compareAtCents"
--   FROM "PrixAvantPromotion" a
--   WHERE a."variantId" = v."id" AND a."campagne" = 'black-friday-2026';
--   DELETE FROM "PrixAvantPromotion" WHERE "campagne" = 'black-friday-2026';
--
-- Livraison : comme LedPerf, 2,90 € pour la France sous le seuil (offerte dès
-- 50 €, inchangé). LedPerf facture 4,90 € quand le colis contient une ampoule
-- xénon : ici, 2,90 € partout.

CREATE TABLE "PrixAvantPromotion" (
    "variantId" TEXT NOT NULL,
    "priceCents" INTEGER NOT NULL,
    "compareAtCents" INTEGER,
    "campagne" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "PrixAvantPromotion_pkey" PRIMARY KEY ("variantId")
);

CREATE TEMP TABLE "_prix_ledperf" ("sku" TEXT PRIMARY KEY, "cents" INTEGER NOT NULL);

