CREATE TEMP TABLE "_nouveaux_prix" AS
SELECT
  v."id",
  v."priceCents" AS "ancien",
  v."compareAtCents" AS "ancienBarre",
  GREATEST(
    CASE
      WHEN l."cents" IS NOT NULL THEN ROUND(l."cents"::numeric * 0.8)::int - 100
      ELSE FLOOR(GREATEST(v."priceCents" + 1, CEIL((v."priceCents" - 50)::numeric / 0.95)) * 0.8)::int - 100
    END,
    CEIL(v."priceCents"::numeric * 0.5)::int,
    COALESCE(CEIL(v."costCents"::numeric * 1.2)::int, 0)
  ) AS "nouveau"
FROM "ProductVariant" v
LEFT JOIN "_prix_ledperf" l ON l."sku" = v."sku"
WHERE v."isDemo" = false AND v."active" = true AND v."priceCents" > 0;

DELETE FROM "_nouveaux_prix" WHERE "nouveau" >= "ancien";

INSERT INTO "PrixAvantPromotion" ("variantId", "priceCents", "compareAtCents", "campagne")
SELECT "id", "ancien", "ancienBarre", 'black-friday-2026' FROM "_nouveaux_prix";

UPDATE "ProductVariant" v
SET "compareAtCents" = n."ancien", "priceCents" = n."nouveau", "updatedAt" = CURRENT_TIMESTAMP
FROM "_nouveaux_prix" n
WHERE n."id" = v."id";

UPDATE "ShippingMethod" m
SET "priceCents" = 290
FROM "ShippingZone" z
WHERE m."zoneId" = z."id" AND 'FR' = ANY(z."countries") AND m."active" = true AND m."priceCents" = 590;

DROP TABLE "_nouveaux_prix";
DROP TABLE "_prix_ledperf";
